"""Daily PSP settlement reconciliation matching engine.

Standard library only. Requires Python 3.10+.
"""

from __future__ import annotations

import re
from datetime import date, datetime, time, timedelta
from zoneinfo import ZoneInfo

_NY = ZoneInfo("America/New_York")
_CUTOFF = time(17, 0)

_FEE = "FEE"
_CB = "CHARGEBACK"
_CBR = "CHARGEBACK_REVERSAL"

# ISO 4217 minor-unit exponents. Any currency not listed here uses 2.
_ZERO_DECIMAL = {
    "BIF", "CLP", "DJF", "GNF", "ISK", "JPY", "KMF", "KRW",
    "PYG", "RWF", "UGX", "UYI", "VND", "VUV", "XAF", "XOF", "XPF",
}
_THREE_DECIMAL = {"BHD", "IQD", "JOD", "KWD", "LYD", "OMR", "TND"}
_FOUR_DECIMAL = {"CLF", "UYW"}

_NUMBER_RE = re.compile(r"^([0-9]+\.?[0-9]*|\.[0-9]+)$")


def _exponent(currency: str) -> int:
    code = currency.strip().upper()
    if code in _ZERO_DECIMAL:
        return 0
    if code in _THREE_DECIMAL:
        return 3
    if code in _FOUR_DECIMAL:
        return 4
    return 2


def parse_minor_units(text: str, currency: str) -> int:
    """Convert a processor amount string to exact integer minor units.

    Accepts thousands separators, accounting-style negatives "(12.34)"
    and a leading minus sign. Raises ValueError if the amount is malformed
    or carries precision beyond the currency's ISO 4217 minor unit.
    """
    if not isinstance(text, str):
        raise ValueError(f"amount must be a string, got {text!r}")

    s = text.strip().replace(",", "")
    negative = False
    if s.startswith("(") and s.endswith(")"):
        negative = True
        s = s[1:-1].strip()
    elif s.startswith("-"):
        negative = True
        s = s[1:].strip()

    if not _NUMBER_RE.match(s):
        raise ValueError(f"malformed amount {text!r}")

    exp = _exponent(currency)
    int_part, _, frac = s.partition(".")
    if len(frac) > exp and frac[exp:].strip("0"):
        raise ValueError(
            f"amount {text!r} has more precision than {currency} allows ({exp} decimals)"
        )
    frac = frac[:exp].ljust(exp, "0")
    minor = int((int_part or "0") + frac)
    return -minor if negative else minor


def _parse_utc(event_time: str) -> datetime:
    s = event_time.strip()
    if s.endswith(("Z", "z")):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        raise ValueError(f"event_time without UTC offset: {event_time!r}")
    return dt


def _business_date(event_time: str, holidays: frozenset[date]) -> date:
    local = _parse_utc(event_time).astimezone(_NY)
    d = local.date()
    if local.time() >= _CUTOFF:
        d += timedelta(days=1)
    while d.weekday() >= 5 or d in holidays:
        d += timedelta(days=1)
    return d


def _accumulate(groups: dict, key: tuple, amount: int, bdate: date) -> None:
    g = groups.get(key)
    if g is None:
        groups[key] = {"amount": amount, "date": bdate}
    else:
        g["amount"] += amount
        if bdate > g["date"]:
            g["date"] = bdate


def reconcile(
    ledger_rows: list[dict],
    settlement_lines: list[dict],
    holidays: list[str],
) -> list[dict]:
    hol = frozenset(date.fromisoformat(h.strip()) for h in holidays)

    # Ledger side. FEE rows are not reconciled.
    ledger: dict = {}
    for row in ledger_rows:
        typ = row["type"]
        if typ == _FEE:
            continue
        key = (row["psp_ref"], typ, row["currency"])
        _accumulate(
            ledger,
            key,
            int(row["amount_minor"]),
            date.fromisoformat(row["business_date"]),
        )

    # Settlement side. Only the highest file_seq per batch is live.
    latest_seq: dict[str, int] = {}
    for line in settlement_lines:
        batch = line["batch_id"]
        seq = int(line["file_seq"])
        if batch not in latest_seq or seq > latest_seq[batch]:
            latest_seq[batch] = seq

    settlement: dict = {}
    for line in settlement_lines:
        if int(line["file_seq"]) != latest_seq[line["batch_id"]]:
            continue
        if line["line_type"] == _FEE:
            continue
        key = (line["psp_ref"], line["line_type"], line["currency"])
        amount = parse_minor_units(line["amount"], line["currency"])
        bdate = _business_date(line["event_time"], hol)
        _accumulate(settlement, key, amount, bdate)

    # Chargeback netting, applied before the general comparison.
    cb_pairs = {(psp, cur) for (psp, typ, cur) in settlement if typ in (_CB, _CBR)}
    for psp, cur in sorted(cb_pairs):
        k_cb = (psp, _CB, cur)
        k_cbr = (psp, _CBR, cur)
        if k_cb not in settlement or k_cbr not in settlement:
            continue
        if k_cb in ledger or k_cbr in ledger:
            continue
        if settlement[k_cb]["amount"] + settlement[k_cbr]["amount"] == 0:
            del settlement[k_cb]
            del settlement[k_cbr]

    # Compare each group key present on either side.
    results: list[dict] = []
    for key in set(settlement) | set(ledger):
        psp, typ, cur = key
        s = settlement.get(key)
        l = ledger.get(key)

        if s is not None and l is None:
            brk, delta = "MISSING_IN_LEDGER", s["amount"]
        elif s is None and l is not None:
            brk, delta = "MISSING_IN_SETTLEMENT", -l["amount"]
        elif s["amount"] != l["amount"]:
            brk, delta = "AMOUNT_MISMATCH", s["amount"] - l["amount"]
        elif s["date"] != l["date"]:
            brk, delta = "TIMING", 0
        else:
            continue

        results.append(
            {
                "psp_ref": psp,
                "type": typ,
                "currency": cur,
                "break": brk,
                "delta_minor": delta,
            }
        )

    results.sort(key=lambda r: (r["psp_ref"], r["type"], r["currency"]))
    return results
